using System;
using System.Collections.Generic;
using System.Linq;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>
    /// One four-sided facade panel cut from a surface. Travels between components
    /// as a single opaque "Panel" value.
    /// </summary>
    public sealed class Panel : IBettaValue
    {
        private readonly Point3d[] _corners;

        public Panel(IReadOnlyList<Point3d> corners, int index)
        {
            if (corners == null || corners.Count != 4)
                throw new ArgumentException("A panel needs exactly four corners.", nameof(corners));

            _corners = corners.ToArray();
            Index = index;
            Outline = new PolylineCurve(new[] { _corners[0], _corners[1], _corners[2], _corners[3], _corners[0] });
            Area = TriangleArea(_corners[0], _corners[1], _corners[2]) + TriangleArea(_corners[0], _corners[2], _corners[3]);
            Deviation = ComputeDeviation(_corners);
        }

        /// <summary>The four corners, in order around the panel.</summary>
        public IReadOnlyList<Point3d> Corners => _corners;

        /// <summary>Closed outline through the four corners.</summary>
        public Curve Outline { get; }

        /// <summary>Area of the panel (sum of the two triangles 0-1-2 and 0-2-3).</summary>
        public double Area { get; }

        /// <summary>Distance from the fourth corner to the plane through the other three.</summary>
        public double Deviation { get; }

        /// <summary>Index of the panel in its grid.</summary>
        public int Index { get; }

        public Point3d Center => new Point3d(
            _corners.Average(p => p.X), _corners.Average(p => p.Y), _corners.Average(p => p.Z));

        /// <summary>Edge lengths: 0-1, 1-2, 2-3, 3-0.</summary>
        public double[] EdgeLengths() => new[]
        {
            _corners[0].DistanceTo(_corners[1]),
            _corners[1].DistanceTo(_corners[2]),
            _corners[2].DistanceTo(_corners[3]),
            _corners[3].DistanceTo(_corners[0]),
        };

        /// <summary>Diagonal lengths: 0-2, 1-3.</summary>
        public double[] DiagonalLengths() => new[]
        {
            _corners[0].DistanceTo(_corners[2]),
            _corners[1].DistanceTo(_corners[3]),
        };

        /// <summary>Rectangle width used for nesting and cut lists: mean of the first and third edges.</summary>
        public double NestWidth
        {
            get { var e = EdgeLengths(); return (e[0] + e[2]) / 2.0; }
        }

        /// <summary>Rectangle height used for nesting and cut lists: mean of the second and fourth edges.</summary>
        public double NestHeight
        {
            get { var e = EdgeLengths(); return (e[1] + e[3]) / 2.0; }
        }

        public override string ToString() => $"Panel {Index} (area {Area:0.###}, deviation {Deviation:0.###})";

        private static double TriangleArea(Point3d a, Point3d b, Point3d c)
            => 0.5 * Vector3d.CrossProduct(b - a, c - a).Length;

        private static double ComputeDeviation(Point3d[] c)
        {
            var normal = Vector3d.CrossProduct(c[1] - c[0], c[2] - c[0]);
            double len = normal.Length;
            if (len < 1e-12) return 0.0; // first three corners collinear: no defined plane
            return Math.Abs((c[3] - c[0]) * normal) / len;
        }
    }
}

