using System;
using System.Collections.Generic;
using System.Linq;
using Betta.Attributes;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    [GrasshopperCollection("Facade", "Panels")]
    public interface IPanelTools : IBettaCollection
    {
        [GrasshopperMethod("Panelize Surface", "Divide a surface's domain evenly into four-sided panels")]
        (List<Panel> Panels, List<Curve> Outlines) PanelizeSurface(
            [GrasshopperParameter("Surface", "S", "Surface to panelize")] Surface surface,
            [GrasshopperParameter("U Count", "U", "Number of panels in the U direction", DefaultValue = 10)] int uCount,
            [GrasshopperParameter("V Count", "V", "Number of panels in the V direction", DefaultValue = 6)] int vCount);

        [GrasshopperMethod("Panel Info", "Deconstruct a panel")]
        (List<Point3d> Corners, Curve Outline, double Area, Point3d Center, int Index) PanelInfo(
            [GrasshopperParameter("Panel", "P", "Panel to deconstruct")] Panel panel);
    }

    public class PanelTools : IPanelTools
    {
        public (List<Panel> Panels, List<Curve> Outlines) PanelizeSurface(Surface surface, int uCount, int vCount)
        {
            if (surface == null) throw new ArgumentNullException(nameof(surface), "Surface is required.");
            if (uCount < 1) throw new ArgumentOutOfRangeException(nameof(uCount), "U Count must be at least 1.");
            if (vCount < 1) throw new ArgumentOutOfRangeException(nameof(vCount), "V Count must be at least 1.");

            Interval du = surface.Domain(0);
            Interval dv = surface.Domain(1);

            var panels = new List<Panel>(uCount * vCount);
            for (int j = 0; j < vCount; j++)
            {
                double v0 = dv.ParameterAt((double)j / vCount);
                double v1 = dv.ParameterAt((double)(j + 1) / vCount);
                for (int i = 0; i < uCount; i++)
                {
                    double u0 = du.ParameterAt((double)i / uCount);
                    double u1 = du.ParameterAt((double)(i + 1) / uCount);
                    var corners = new[]
                    {
                        surface.PointAt(u0, v0),
                        surface.PointAt(u1, v0),
                        surface.PointAt(u1, v1),
                        surface.PointAt(u0, v1),
                    };
                    panels.Add(new Panel(corners, j * uCount + i));
                }
            }

            return (panels, panels.Select(p => p.Outline.DuplicateCurve()).ToList());
        }

        public (List<Point3d> Corners, Curve Outline, double Area, Point3d Center, int Index) PanelInfo(Panel panel)
        {
            if (panel == null) throw new ArgumentNullException(nameof(panel), "Panel is required.");
            return (panel.Corners.ToList(), panel.Outline.DuplicateCurve(), panel.Area, panel.Center, panel.Index);
        }
    }
}

