using System;
using System.Collections.Generic;
using System.Linq;
using Betta.Attributes;
using Betta.Interfaces;

namespace BenchPlugin.Facade
{
    [GrasshopperCollection("Facade", "Analysis")]
    public interface IPanelAnalysis : IBettaCollection
    {
        [GrasshopperMethod("Planarity", "Planarity deviation of each panel and whether it is flat")]
        (List<double> Deviation, List<bool> Flat, int FlatCount) Planarity(
            [GrasshopperParameter("Panels", "P", "Panels to check")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", "T", "Largest deviation that counts as flat", DefaultValue = 0.5)] double tolerance,
            IBettaReport report);

        [GrasshopperMethod("Classify Panels", "Classify panels as flat, cold-bent or custom")]
        (List<string> Type, int FlatCount, int ColdBentCount, int CustomCount) ClassifyPanels(
            [GrasshopperParameter("Panels", "P", "Panels to classify")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", "T", "Flat tolerance; cold-bent up to 10 times this", DefaultValue = 0.5)] double tolerance);

        [GrasshopperMethod("Panel Stats", "Area statistics of a set of panels")]
        (double TotalArea, double MinArea, double MaxArea, double MeanArea) PanelStats(
            [GrasshopperParameter("Panels", "P", "Panels to measure")] List<Panel> panels);
    }

    public class PanelAnalysis : IPanelAnalysis
    {
        public (List<double> Deviation, List<bool> Flat, int FlatCount) Planarity(
            List<Panel> panels, double tolerance, IBettaReport report)
        {
            var list = (panels ?? new List<Panel>()).Where(p => p != null).ToList();
            var deviation = list.Select(p => p.Deviation).ToList();
            var flat = deviation.Select(d => d <= tolerance).ToList();
            int flatCount = flat.Count(f => f);
            int notFlat = list.Count - flatCount;

            if (notFlat * 2 > list.Count)
                report?.Warning($"{notFlat} of {list.Count} panels are not flat (deviation above {tolerance}).");

            return (deviation, flat, flatCount);
        }

        public (List<string> Type, int FlatCount, int ColdBentCount, int CustomCount) ClassifyPanels(
            List<Panel> panels, double tolerance)
        {
            var types = (panels ?? new List<Panel>())
                .Where(p => p != null)
                .Select(p => p.Deviation <= tolerance ? "flat"
                           : p.Deviation <= 10.0 * tolerance ? "cold-bent"
                           : "custom")
                .ToList();

            return (types,
                types.Count(t => t == "flat"),
                types.Count(t => t == "cold-bent"),
                types.Count(t => t == "custom"));
        }

        public (double TotalArea, double MinArea, double MaxArea, double MeanArea) PanelStats(List<Panel> panels)
        {
            var areas = (panels ?? new List<Panel>()).Where(p => p != null).Select(p => p.Area).ToList();
            if (areas.Count == 0) throw new ArgumentException("There are no panels.", nameof(panels));
            return (areas.Sum(), areas.Min(), areas.Max(), areas.Average());
        }
    }
}

