using System.Threading.Tasks;
using Betta.Attributes;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    [GrasshopperCollection("Facade", "Fabrication")]
    public interface IPanelFabrication : IBettaCollection
    {
        [GrasshopperMethod("Group Identical Panels", "Group panels whose sorted edge and diagonal lengths match within a tolerance")]
        (List<int> Group, int GroupCount, List<Panel> Representatives) GroupIdenticalPanels(
            [GrasshopperParameter("Panels", "P", "Panels to group")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", "T", "Largest length difference for identical panels", DefaultValue = 1.0)] double tolerance);

        [GrasshopperMethod("Nest On Sheets", "Shelf-nest panel rectangles on sheets")]
        Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> NestOnSheets(
            [GrasshopperParameter("Panels", "P", "Panels to nest")] List<Panel> panels,
            [GrasshopperParameter("Sheet Width", "W", "Sheet width", DefaultValue = 3000.0)] double sheetWidth,
            [GrasshopperParameter("Sheet Height", "H", "Sheet height", DefaultValue = 1500.0)] double sheetHeight,
            [GrasshopperParameter("Spacing", "S", "Gap between parts and from the sheet edge", DefaultValue = 10.0)] double spacing,
            CancellationToken cancellationToken,
            IProgress<int> progress,
            IBettaReport report);

        [GrasshopperMethod("Cut List", "CSV cut list of panels, optionally written to a file")]
        (string CSV, bool Written) CutList(
            [GrasshopperParameter("Panels", "P", "Panels to list")] List<Panel> panels,
            [GrasshopperParameter("Path", "F", "File to write the CSV to", DefaultValue = "")] string path,
            [GrasshopperParameter("Write", "W", "Write the CSV to Path", DefaultValue = false)] bool write);
    }

    public class PanelFabrication : IPanelFabrication
    {
        private const double SheetGap = 100.0;

        public (List<int> Group, int GroupCount, List<Panel> Representatives) GroupIdenticalPanels(
            List<Panel> panels, double tolerance)
        {
            var groups = new List<int>();
            var reps = new List<Panel>();
            var repKeys = new List<(double[] Edges, double[] Diagonals)>();

            foreach (var panel in (panels ?? new List<Panel>()).Where(p => p != null))
            {
                var edges = panel.EdgeLengths().OrderBy(x => x).ToArray();
                var diagonals = panel.DiagonalLengths().OrderBy(x => x).ToArray();

                int group = repKeys.FindIndex(k => Within(k.Edges, edges, tolerance) && Within(k.Diagonals, diagonals, tolerance));
                if (group < 0)
                {
                    group = reps.Count;
                    reps.Add(panel);
                    repKeys.Add((edges, diagonals));
                }
                groups.Add(group);
            }

            return (groups, reps.Count, reps);
        }

        private static bool Within(double[] a, double[] b, double tolerance)
        {
            for (int i = 0; i < a.Length; i++)
                if (Math.Abs(a[i] - b[i]) > tolerance) return false;
            return true;
        }

        public Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> NestOnSheets(
            List<Panel> panels, double sheetWidth, double sheetHeight, double spacing,
            CancellationToken cancellationToken, IProgress<int> progress, IBettaReport report)
        {
            if (sheetWidth <= 0 || sheetHeight <= 0)
                throw new ArgumentOutOfRangeException(nameof(sheetWidth), "Sheet Width and Sheet Height must be positive.");
            if (spacing < 0)
                throw new ArgumentOutOfRangeException(nameof(spacing), "Spacing cannot be negative.");

            var parts = (panels ?? new List<Panel>()).Where(p => p != null).ToList();
            return Task.Run(() => Nest(parts, sheetWidth, sheetHeight, spacing, cancellationToken, progress, report), cancellationToken);
        }

        private static (List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization) Nest(
            List<Panel> panels, double sheetW, double sheetH, double s,
            CancellationToken ct, IProgress<int> progress, IBettaReport report)
        {
            // Usable region of a sheet: [s, sheetW - s] x [s, sheetH - s].
            double maxX = sheetW - s;
            double maxY = sheetH - s;

            var parts = panels
                .Select(p => (W: p.NestWidth, H: p.NestHeight))
                .OrderByDescending(p => p.H)
                .ToList();

            var outlines = new List<Curve>();
            var sheetOf = new List<int>();
            double placedArea = 0;
            int unplaced = 0;

            int sheet = -1;        // current sheet, -1 = none opened yet
            double shelfY = 0;     // bottom of the current shelf
            double shelfH = 0;     // height of the current shelf (0 = empty shelf)
            double cursorX = 0;    // next free x on the current shelf

            bool FitsInShelf(double w, double h) =>
                sheet >= 0 && cursorX + w <= maxX && shelfY + h <= maxY;

            int lastReported = -1;
            for (int n = 0; n < parts.Count; n++)
            {
                ct.ThrowIfCancellationRequested();

                double w = parts[n].W, h = parts[n].H;
                bool fitsSheet = (s + w <= maxX && s + h <= maxY) || (s + h <= maxX && s + w <= maxY);
                if (!fitsSheet)
                {
                    unplaced++;
                }
                else
                {
                    bool placed = false;
                    for (int attempt = 0; attempt < 3 && !placed; attempt++)
                    {
                        if (attempt == 1)
                        {
                            // New shelf above the current one.
                            if (sheet < 0 || shelfH == 0) continue;
                            shelfY += shelfH + s;
                            shelfH = 0;
                            cursorX = s;
                        }
                        else if (attempt == 2)
                        {
                            // New sheet.
                            sheet++;
                            shelfY = s;
                            shelfH = 0;
                            cursorX = s;
                        }

                        double pw, ph;
                        if (FitsInShelf(w, h)) { pw = w; ph = h; }
                        else if (FitsInShelf(h, w)) { pw = h; ph = w; } // only fits turned
                        else continue;

                        double offsetX = sheet * (sheetW + SheetGap);
                        var rect = new Rectangle3d(Plane.WorldXY,
                            new Point3d(offsetX + cursorX, shelfY, 0),
                            new Point3d(offsetX + cursorX + pw, shelfY + ph, 0));
                        outlines.Add(rect.ToNurbsCurve());
                        sheetOf.Add(sheet);
                        placedArea += pw * ph;

                        cursorX += pw + s;
                        shelfH = Math.Max(shelfH, ph);
                        placed = true;
                    }
                    if (!placed) unplaced++; // should not happen: fitsSheet guarantees an empty sheet works
                }

                int pct = parts.Count == 0 ? 100 : (int)((n + 1) * 100L / parts.Count);
                if (pct != lastReported) { progress?.Report(pct); lastReported = pct; }
            }

            int sheetCount = sheet + 1;
            double utilization = sheetCount == 0 ? 0.0 : placedArea / (sheetCount * sheetW * sheetH);

            if (unplaced > 0)
                report?.Warning($"{unplaced} panel(s) fit on no sheet and were not nested.");

            return (outlines, sheetOf, sheetCount, utilization);
        }

        public (string CSV, bool Written) CutList(List<Panel> panels, string path, bool write)
        {
            if (write && string.IsNullOrWhiteSpace(path))
                throw new ArgumentException("Write is true but Path is empty.", nameof(path));

            var inv = CultureInfo.InvariantCulture;
            var sb = new StringBuilder();
            sb.Append("index,width,height,area,deviation\n");
            foreach (var p in (panels ?? new List<Panel>()).Where(p => p != null))
            {
                sb.Append(p.Index.ToString(inv)).Append(',')
                  .Append(p.NestWidth.ToString("R", inv)).Append(',')
                  .Append(p.NestHeight.ToString("R", inv)).Append(',')
                  .Append(p.Area.ToString("R", inv)).Append(',')
                  .Append(p.Deviation.ToString("R", inv)).Append('\n');
            }
            string csv = sb.ToString();

            if (!write) return (csv, false);

            string dir = Path.GetDirectoryName(Path.GetFullPath(path));
            if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
            File.WriteAllText(path, csv);
            return (csv, true);
        }
    }
}

