        {
            if (sheetWidth <= 0 || sheetHeight <= 0)
                throw new ArgumentOutOfRangeException(nameof(sheetWidth), "Sheet Width and Sheet Height must be positive.");
            if (spacing < 0)
                throw new ArgumentOutOfRangeException(nameof(spacing), "Spacing cannot be negative.");

            var parts = (panels ?? new List<Panel>()).Where(p => p != null).ToList();
            return Task.Run(() => Nest(parts, sheetWidth, sheetHeight, spacing, cancellationToken, progress, report), cancellationToken);
        }

        private static (List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization) Nest(
            List<Panel> panels, double sheetW, double sheetH, double s,
            CancellationToken ct, IProgress<int> progress, IBettaReport report)
        {
            // Usable region of a sheet: [s, sheetW - s] x [s, sheetH - s].
            double maxX = sheetW - s;
            double maxY = sheetH - s;

            var parts = panels
                .Select(p => (W: p.NestWidth, H: p.NestHeight))
                .OrderByDescending(p => p.H)
                .ToList();

            var outlines = new List<Curve>();
            var sheetOf = new List<int>();
            double placedArea = 0;
            int unplaced = 0;

            int sheet = -1;        // current sheet, -1 = none opened yet
            double shelfY = 0;     // bottom of the current shelf
            double shelfH = 0;     // height of the current shelf (0 = empty shelf)
            double cursorX = 0;    // next free x on the current shelf

            bool FitsInShelf(double w, double h) =>
                sheet >= 0 && cursorX + w <= maxX && shelfY + h <= maxY;

            int lastReported = -1;
            for (int n = 0; n < parts.Count; n++)
            {
                ct.ThrowIfCancellationRequested();

                double w = parts[n].W, h = parts[n].H;
                bool fitsSheet = (s + w <= maxX && s + h <= maxY) || (s + h <= maxX && s + w <= maxY);
                if (!fitsSheet)
                {
                    unplaced++;
                }
                else
                {
                    bool placed = false;
                    for (int attempt = 0; attempt < 3 && !placed; attempt++)
                    {
                        if (attempt == 1)
                        {
                            // New shelf above the current one.
                            if (sheet < 0 || shelfH == 0) continue;
                            shelfY += shelfH + s;
                            shelfH = 0;
                            cursorX = s;
                        }
                        else if (attempt == 2)
                        {
                            // New sheet.
                            sheet++;
                            shelfY = s;
                            shelfH = 0;
                            cursorX = s;
                        }

                        double pw, ph;
                        if (FitsInShelf(w, h)) { pw = w; ph = h; }
                        else if (FitsInShelf(h, w)) { pw = h; ph = w; } // only fits turned
                        else continue;

                        double offsetX = sheet * (sheetW + SheetGap);
                        var rect = new Rectangle3d(Plane.WorldXY,
                            new Point3d(offsetX + cursorX, shelfY, 0),
                            new Point3d(offsetX + cursorX + pw, shelfY + ph, 0));
                        outlines.Add(rect.ToNurbsCurve());
                        sheetOf.Add(sheet);
                        placedArea += pw * ph;

                        cursorX += pw + s;
                        shelfH = Math.Max(shelfH, ph);
                        placed = true;
                    }
                    if (!placed) unplaced++; // should not happen: fitsSheet guarantees an empty sheet works
                }

                int pct = parts.Count == 0 ? 100 : (int)((n + 1) * 100L / parts.Count);
                if (pct != lastReported) { progress?.Report(pct); lastReported = pct; }
            }

            int sheetCount = sheet + 1;
            double utilization = sheetCount == 0 ? 0.0 : placedArea / (sheetCount * sheetW * sheetH);

            if (unplaced > 0)
                report?.Warning($"{unplaced} panel(s) fit on no sheet and were not nested.");

            return (outlines, sheetOf, sheetCount, utilization);
        }

        public (string CSV, bool Written) CutList(List<Panel> panels, string path, bool write)
        {
            if (write && string.IsNullOrWhiteSpace(path))
                throw new ArgumentException("Write is true but Path is empty.", nameof(path));

            var inv = CultureInfo.InvariantCulture;
            var sb = new StringBuilder();
            sb.Append("index,width,height,area,deviation\n");
            foreach (var p in (panels ?? new List<Panel>()).Where(p => p != null))
            {
                sb.Append(p.Index.ToString(inv)).Append(',')
                  .Append(p.NestWidth.ToString("R", inv)).Append(',')
                  .Append(p.NestHeight.ToString("R", inv)).Append(',')
                  .Append(p.Area.ToString("R", inv)).Append(',')
                  .Append(p.Deviation.ToString("R", inv)).Append('\n');
            }
            string csv = sb.ToString();

            if (!write) return (csv, false);

            string dir = Path.GetDirectoryName(Path.GetFullPath(path));
            if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
            File.WriteAllText(path, csv);
            return (csv, true);
        }
    }
